def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    for color in colors:
        if not any(all(v == color for v in row) for row in grid):
            continue
        for r, row in enumerate(grid):
            cols = [c for c, v in enumerate(row) if v == color]
            if not cols or len(cols) == w:
                continue
            lo, hi = min(cols), max(cols)
            if all(row[c] == color for c in range(lo, hi + 1)):
                for c in range(hi + 1, w):
                    out[r][c] = 1
    return out
